from fastmcp import Server, TextResource
import json

server = Server("config-server")

@server.resource("data://config")
def get_config():
    config = {
        "version": "1.0",
        "debug": True,
        "max_workers": 4,
        "timeout": 30,
        "features": ["caching", "logging", "monitoring"]
    }
    return TextResource(
        uri="data://config",
        text=json.dumps(config, indent=2),
        mime_type="application/json"
    )

if __name__ == "__main__":
    import asyncio
    asyncio.run(server.run())

